            "$type": "ReInvented.Domain.Reporting.Models.RevisionDescriptionItem, ReInvented.Domain.Reporting",
            "Section": "-",
            "Description": "<p>Issued for Use</p>\r\n<p>Generally revised by considering the updated Soil Type i.e., Soil Type A. Also the soil parameters are considered from NCh2369-2023. Below table provides the comparison of previous and the updated seismic coefficients.</p>\r\n<p>For Detailed Seismic Calculations per NCh2369-2023 Refer Annexure 1.1</p>\r\n<table class=\"data-table rev-desc\">\r\n    <thead>\r\n        <tr>\r\n            <th>Seismic Component</th>\r\n            <th>Previous</th>\r\n            <th>Current</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Support Structure &amp; Bridge - Horizontal</td>\r\n            <td>0.384</td>\r\n            <td>0.6594</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Support Structure &amp; Bridge - Vertical</td>\r\n            <td>0.320</td>\r\n            <td>0.680</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Tank - Impulsive</td>\r\n            <td>0.384</td>\r\n            <td>0.6594</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Tank - Convective</td>\r\n            <td>0.048</td>\r\n            <td>0.1013</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Tank - Vertical</td>\r\n            <td>0.256</td>\r\n            <td>0.4396</td>\r\n        </tr>\r\n    </tbody>\r\n</table>"
